def MemSchauderSum (b : NormalizedSchauderBasis 𝕜 X) {Y : Type*}
    [NormedAddCommGroup Y] (y : ℕ → Y) : Prop :=
  ∃ x : X, ∀ n, b.coord n x = (‖y n‖ : 𝕜)

